// ts/constants.ts
var WORD_SIZE = 32;
var WORD_LAST_INDEX = 31;
var BYTE_TO_BITS = 8;
var MAX_TOTAL_FIELDS = 28;
var MAX_DYNAMIC_FIELDS = 5;
var LayoutOffsets = {
  TOTAL_LENGTH: (WORD_SIZE - 2) * BYTE_TO_BITS,
  NUM_STATIC_FIELDS: (WORD_SIZE - 2 - 1) * BYTE_TO_BITS,
  NUM_DYNAMIC_FIELDS: (WORD_SIZE - 2 - 1 - 1) * BYTE_TO_BITS
};

